CREATE TABLE "share_popups" (
  "api_key_id" text PRIMARY KEY REFERENCES "api_keys" ("id") ON DELETE CASCADE,
  "enabled" integer NOT NULL DEFAULT false CHECK ("enabled" IN (0, 1)),
  "image" blob,
  "image_mime" text,
  "title" text,
  "body" text,
  CONSTRAINT "share_popups_image_mime_check" CHECK ("image_mime" IS NULL OR "image_mime" IN ('image/png', 'image/jpeg', 'image/webp', 'image/gif')),
  CONSTRAINT "share_popups_image_size_check" CHECK ("image" IS NULL OR length("image") <= 2097152)
);
--> statement-breakpoint

CREATE TABLE "share_links" (
  "id" text PRIMARY KEY,
  "api_key_id" text NOT NULL REFERENCES "api_keys" ("id") ON DELETE CASCADE,
  "token_hash" text NOT NULL,
  "token_encrypted" blob,
  "kind" text NOT NULL DEFAULT 'enroll',
  "active" integer NOT NULL DEFAULT true CHECK ("active" IN (0, 1)),
  "created_at" text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  "expires_at" text,
  "last_viewed_at" text,
  CONSTRAINT "share_links_kind_check" CHECK ("kind" IN ('enroll', 'handoff'))
);
